package org.beckenburg.editor;

import java.nio.*;
import java.nio.file.*;
import java.util.*;
import org.beckenburg.editor.EditorMeshPipeline.*;

public final class EditorSurfaceTransformTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static void near(double a,double b){check(Math.abs(a-b)<1e-9,"Surface result "+a+" != "+b);}
    private interface Action{void run()throws Exception;}
    private static void refuse(Action a)throws Exception{try{a.run();throw new AssertionError("Expected native surface refusal");}catch(IllegalArgumentException|IllegalStateException expected){}}
    public static Mesh fixture(){var n=new Normal(1,0,1);var a=new Vertex(0,0,0,0,0,n);var b=new Vertex(2,2,0,1,0,n);var c=new Vertex(0,0,2,0,1,n);return new Mesh("surface.obj",List.of(new Triangle("sloped",a,b,c),new Triangle("other",new Vertex(6,0,0,0,0),new Vertex(7,0,0,1,0),new Vertex(6,1,0,0,1))),0);}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("native-surface-");try{
            var p=EditorTopologyProject.fromMesh(fixture(),"0".repeat(64),root.resolve("surface.btop"));var before=p.snapshot();var basis=EditorMeshBasis.face(before,0);double s=Math.sqrt(.5);near(basis.tangent().x(),s);near(basis.tangent().y(),s);near(basis.bitangent().z(),1);near(basis.normal().x(),s);near(basis.normal().y(),-s);near(basis.normal().z(),0);check(basis.normal().z()!=EditorMeshNormals.unit(fixture().triangles().get(0).a().normal()).z(),"Surface axes derive from actual geometry rather than shading normals");
            var ids=Set.of(0L,1L,2L);var history=new EditorHistory<>(p,20);var preview=p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,2,90,true,0);check(p.snapshot()==before,"Native surface preview does not mutate authority");var v=preview.snapshot().vertices().get(0);near(v.x(),2d/3+Math.sqrt(2)/3);near(v.y(),v.x());near(v.z(),2d/3-2*Math.sqrt(2)/3);var n=preview.snapshot().faces().get(0).a().normal();near(n.x(),.5-s);near(n.y(),-.5-s);near(n.z(),s);check(preview.snapshot().vertices().subList(3,6).equals(before.vertices().subList(3,6)),"Other native part unchanged");
            p.cancelPreview(preview);refuse(()->p.applyPreview(preview));check(p.snapshot()==before,"Canceled surface candidate cannot commit");var edit=p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,2,90,true,0);history.execute(()->p.applyPreview(edit));var moved=p.snapshot();check(history.undo()&&p.snapshot().equals(before)&&history.redo()&&p.snapshot().equals(moved),"Same shared history for surface transforms");p.save();check(ByteBuffer.wrap(Files.readAllBytes(p.documentPath())).getInt(4)==2&&EditorTopologyProject.open(p.documentPath()).snapshot().equals(moved),"Existing native v2 schema retains exact baked surface geometry/normals");EditorGlbWriter.validate(p.mesh(),EditorGlbWriter.encode(p.mesh()));
            var stale=p.previewTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,2,false,0);history.undo();refuse(()->p.applyPreview(stale));check(p.snapshot().equals(before),"Stale surface anchor/candidate refuses");
            var scale=p.previewTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,2,true,0);n=scale.snapshot().faces().get(0).a().normal();double length=Math.sqrt(1.625);near(n.x(),.75/length);near(n.y(),-.25/length);near(n.z(),1/length);check(scale.snapshot().faces().get(0).a().u()==before.faces().get(0).a().u(),"UVs preserved independently of surface basis");
            long revision=p.revision();for(Action bad:List.<Action>of(()->p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,2,360,true,0),()->p.previewTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,1,false,0),()->p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,3,90,false,0),()->p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,0,Double.NaN,false,0),()->p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,0,90,false,999),()->p.previewTransform(Set.of(999L),EditorTopologyProject.Transform.ROTATE,0,90,false,0)))refuse(bad);check(p.revision()==revision&&p.snapshot().equals(before),"Invalid surface transforms preserve native snapshot and epoch");
            for(var camera:List.<EditorMeshPicking.Projector>of(EditorMeshPicking.Projection.FRONT,EditorMeshPicking.Projection.ISOMETRIC,new EditorMeshPicking.Camera(0,0,0,4,35,25)))for(int axis=0;axis<3;axis++){var d=basis.axis(axis);var a=camera.project(.2,.3,.4);var b=camera.project(.2+d.x()*.3,.3+d.y()*.3,.4+d.z()*.3);var screen=camera.direction(.2,.3,.4,d);if(Math.hypot(screen.x(),screen.y())>1e-10)near(camera.deltaAlong(.2,.3,.4,d,b.x()-a.x(),b.y()-a.y()),.3);}
            if(args.length>0){var vertices=new ArrayList<EditorTopologyProject.Vertex>();var faces=new ArrayList<EditorTopologyProject.Face>();for(int i=0;i<EditorMeshPipeline.MAX_TRIANGLES;i++){long id=(long)i*3;double x=i*4;vertices.add(new EditorTopologyProject.Vertex(id,"maximum",x,0,0));vertices.add(new EditorTopologyProject.Vertex(id+1,"maximum",x+2,2,0));vertices.add(new EditorTopologyProject.Vertex(id+2,"maximum",x,0,2));faces.add(new EditorTopologyProject.Face(i,"maximum",new EditorTopologyProject.Corner(id,0,0,new Normal(1,0,1)),new EditorTopologyProject.Corner(id+1,1,0,new Normal(1,0,1)),new EditorTopologyProject.Corner(id+2,0,1,new Normal(1,0,1))));}var maximum=new EditorTopologyProject.State(before.sceneId(),before.sourceFingerprint(),"maximum",0,vertices,faces);p.restore(maximum);var selected=new HashSet<Long>();for(var vertex:vertices)selected.add(vertex.id());var candidate=p.previewTransform(selected,EditorTopologyProject.Transform.ROTATE,2,15,false,0);check(candidate.snapshot().faces().size()==120000&&candidate.snapshot().vertices().size()==360000,"Maximum native surface transform under256MiB");}
            System.out.println("PASS native surface transforms: actual face basis, geometric/shading separation, preview/cancel/stale/parameter guards, shared history/native reopen, inverse-transpose normals, UV/part identity, real GLB and arbitrary-direction camera inversion");
        }finally{try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
